"""HTTP client wrapper for talking to a JSON REST API."""

from __future__ import annotations

from typing import Any, Mapping, Optional

import httpx


class ApiError(RuntimeError):
    """Raised when a request fails or the API returns an error response."""


class RestClient:
    """Thin wrapper around :class:`httpx.Client` returning decoded JSON."""

    def __init__(
        self,
        base_url: Optional[str] = None,
        *,
        timeout: float = 10.0,
        headers: Optional[Mapping[str, str]] = None,
        client: Optional[httpx.Client] = None,
    ) -> None:
        self._owns_client = client is None
        self._client = client or httpx.Client(
            base_url=base_url,
            timeout=timeout,
            headers=dict(headers) if headers else None,
        )

    def get(
        self,
        path: str,
        *,
        params: Optional[Mapping[str, Any]] = None,
    ) -> Any:
        """GET ``path`` and return the decoded JSON body."""
        return self._request("GET", path, params=params)

    def _request(
        self,
        method: str,
        path: str,
        *,
        params: Optional[Mapping[str, Any]] = None,
    ) -> Any:
        try:
            response = self._client.request(method, path, params=params)
            response.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise ApiError(
                f"{method} {exc.request.url} returned "
                f"HTTP {exc.response.status_code}"
            ) from exc
        except httpx.RequestError as exc:
            raise ApiError(f"{method} {exc.request.url} failed: {exc}") from exc

        try:
            return response.json()
        except ValueError as exc:
            raise ApiError(
                f"{method} {response.request.url} did not return valid JSON"
            ) from exc

    def close(self) -> None:
        if self._owns_client:
            self._client.close()

    def __enter__(self) -> "RestClient":
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()

import httpx
import pytest

from api_fetcher.client import ApiError, RestClient


def make_client(handler):
    transport = httpx.MockTransport(handler)
    return RestClient(
        client=httpx.Client(base_url="https://api.example.com", transport=transport)
    )


def test_get_returns_decoded_json():
    def handler(request):
        assert request.method == "GET"
        assert request.url.path == "/items"
        assert request.url.params["page"] == "2"
        return httpx.Response(200, json={"items": [1, 2, 3]})

    with make_client(handler) as client:
        assert client.get("/items", params={"page": 2}) == {"items": [1, 2, 3]}


def test_get_raises_api_error_on_http_error():
    def handler(request):
        return httpx.Response(500, json={"error": "boom"})

    with make_client(handler) as client:
        with pytest.raises(ApiError, match="HTTP 500"):
            client.get("/items")


def test_get_raises_api_error_on_transport_error():
    def handler(request):
        raise httpx.ConnectError("connection refused", request=request)

    with make_client(handler) as client:
        with pytest.raises(ApiError, match="failed"):
            client.get("/items")


def test_get_raises_api_error_on_invalid_json():
    def handler(request):
        return httpx.Response(200, text="not json")

    with make_client(handler) as client:
        with pytest.raises(ApiError, match="valid JSON"):
            client.get("/items")

import pytest

from api_fetcher.cli import main, parse_headers


def test_parse_headers():
    assert parse_headers(["Authorization: Bearer token", "X-A: 1"]) == {
        "Authorization": "Bearer token",
        "X-A": "1",
    }


def test_parse_headers_rejects_missing_colon():
    with pytest.raises(ValueError):
        parse_headers(["nope"])


def test_main_prints_error_for_bad_header(capsys):
    exit_code = main(["--header", "nope", "https://api.example.com"])
    assert exit_code == 2
    assert "invalid header" in capsys.readouterr().err

